// Custom Worker entry (wrangler.jsonc "main"). Large public media in R2
// (the Omusha splat, the intro video) is served here directly, before
// OpenNext: through a Next route handler it streamed at ~40 KB/s. Every
// other request goes to the OpenNext worker as before.
// See src/integrations/museum-assets/edge.ts.
import {
  type MediaBucket,
  serveMedia,
} from "./src/integrations/museum-assets/edge";

// @ts-ignore: .open-next/worker.js is generated by `opennextjs-cloudflare build`.
import handler from "./.open-next/worker.js";

type Env = { MUSEUM_ASSETS?: MediaBucket } & Record<string, unknown>;
type Next = { fetch(req: Request, env: Env, ctx: unknown): Promise<Response> };

export default {
  async fetch(request: Request, env: Env, ctx: unknown): Promise<Response> {
    try {
      const media = await serveMedia(request, env.MUSEUM_ASSETS);
      if (media) return media;
    } catch {
      // Fall through: the Next route answers (slower, but it works).
    }
    return (handler as Next).fetch(request, env, ctx);
  },
};
